class App:
    def __init__(self):
        self.config = {}
        self.features = {}
        self._initialize_default_config()

    def _initialize_default_config(self):
        """初始化默认配置"""
        self.config = {
            'enabled': True,
            'debug': False,
            'max_retries': 3,
            'timeout': 30
        }

    def _load_config(self, config_dict=None):
        """加载配置"""
        if config_dict:
            self.config.update(config_dict)
        return self.config

    def add_feature(self, feature_name, feature_config=None, init_callback=None, process_callback=None):
        """添加新功能方法

        Args:
            feature_name: 功能名称
            feature_config: 功能配置字典
            init_callback: 初始化回调函数
            process_callback: 业务处理回调函数

        Returns:
            bool: 功能是否添加成功
        """
        if feature_name in self.features:
            print(f"Feature '{feature_name}' already exists")
            return False

        # 功能初始化
        feature = {
            'name': feature_name,
            'config': feature_config or {},
            'enabled': True,
            'init_callback': init_callback,
            'process_callback': process_callback,
            'initialized': False
        }

        # 配置处理
        feature_config = feature.get('config', {})
        if not isinstance(feature_config, dict):
            feature_config = {}

        # 合并全局配置到功能配置
        for key, value in self.config.items():
            if key not in feature_config:
                feature_config[key] = value
        feature['config'] = feature_config

        # 执行业务逻辑实现
        if init_callback and callable(init_callback):
            try:
                init_callback(feature)
                feature['initialized'] = True
            except Exception as e:
                print(f"Feature initialization failed: {e}")
                feature['initialized'] = False

        self.features[feature_name] = feature
        print(f"Feature '{feature_name}' added successfully")
        return True

    def execute_feature(self, feature_name, data=None):
        """执行指定功能

        Args:
            feature_name: 功能名称
            data: 传入数据

        Returns:
            处理结果
        """
        if feature_name not in self.features:
            print(f"Feature '{feature_name}' not found")
            return None

        feature = self.features[feature_name]

        if not feature.get('enabled'):
            print(f"Feature '{feature_name}' is disabled")
            return None

        if not feature.get('initialized'):
            print(f"Feature '{feature_name}' not initialized")
            return None

        process_callback = feature.get('process_callback')
        if process_callback and callable(process_callback):
            return process_callback(data, feature['config'])

        return data

    def remove_feature(self, feature_name):
        """移除功能"""
        if feature_name in self.features:
            del self.features[feature_name]
            return True
        return False

    def enable_feature(self, feature_name):
        """启用功能"""
        if feature_name in self.features:
            self.features[feature_name]['enabled'] = True
            return True
        return False

    def disable_feature(self, feature_name):
        """禁用功能"""
        if feature_name in self.features:
            self.features[feature_name]['enabled'] = False
            return True
        return False

    def list_features(self):
        """列出所有功能"""
        return {name: {
            'enabled': feat['enabled'],
            'initialized': feat['initialized'],
            'config': feat['config']
        } for name, feat in self.features.items()}

    def run(self):
        pass

