import os

def add_feature(data, config=None):
    """
    新增独立feature功能函数

    Args:
        data: 输入数据
        config: 配置参数字典（可选）
            - enabled: 是否启用该功能，默认True
            - feature_type: 功能类型，如'transform', 'filter', 'validate'
            - options: 功能特定选项

    Returns:
        处理后的数据或结果字典
    """
    if config is None:
        config = {}

    # 获取配置参数
    enabled = config.get('enabled', True)
    feature_type = config.get('feature_type', 'default')
    options = config.get('options', {})

    if not enabled:
        return {
            'success': False,
            'data': data,
            'message': 'Feature is disabled'
        }

    # 根据类型执行相应逻辑
    if feature_type == 'transform':
        result = _transform_data(data, options)
    elif feature_type == 'filter':
        result = _filter_data(data, options)
    elif feature_type == 'validate':
        result = _validate_data(data, options)
    else:
        result = _default_process(data, options)

    return result


def _transform_data(data, options):
    """数据转换逻辑"""
    transformation_type = options.get('type', 'upper')

    if transformation_type == 'upper':
        processed = str(data).upper()
    elif transformation_type == 'lower':
        processed = str(data).lower()
    elif transformation_type == 'reverse':
        processed = str(data)[::-1]
    else:
        processed = data

    return {
        'success': True,
        'data': processed,
        'type': 'transform',
        'transformation': transformation_type
    }


def _filter_data(data, options):
    """数据过滤逻辑"""
    filter_condition = options.get('condition', 'all')
    min_length = options.get('min_length', 0)

    if isinstance(data, (list, tuple)):
        if filter_condition == 'non_empty':
            filtered = [item for item in data if item]
        elif filter_condition == 'by_length':
            filtered = [item for item in data if len(str(item)) >= min_length]
        else:
            filtered = data
    else:
        filtered = data

    return {
        'success': True,
        'data': filtered,
        'type': 'filter',
        'condition': filter_condition
    }


def _validate_data(data, options):
    """数据验证逻辑"""
    required_type = options.get('required_type', None)
    required_length = options.get('required_length', None)

    errors = []

    if required_type and not isinstance(data, required_type):
        errors.append(f"Type mismatch: expected {required_type}")

    if required_length and len(str(data)) < required_length:
        errors.append(f"Length too short: minimum {required_length}")

    return {
        'success': len(errors) == 0,
        'data': data,
        'type': 'validate',
        'errors': errors if errors else None
    }


def _default_process(data, options):
    """默认处理逻辑"""
    return {
        'success': True,
        'data': data,
        'type': 'default'
    }


